<script>

    document.addEventListener('DOMContentLoaded', function() {
        const colorToggle = document.getElementById('toggle-brand-colors');
        const isDarkMode = document.documentElement.classList.contains('dark');
        const svgIcons = document.querySelectorAll('.tool-card svg');

        // Ajouter des styles CSS pour les transitions et gestion des versions mono/couleur
        document.head.insertAdjacentHTML('beforeend', `
          <style>
            /* Transition pour tous les éléments SVG */
            .svg-part {
              transition: fill 0.5s ease;
            }

            /* Styles pour les versions mono/couleur */
            .mono-version {
              opacity: 0;
              transition: opacity 0.5s ease;
            }

            .color-version {
              opacity: 1;
              transition: opacity 0.5s ease;
            }

            /* Classe ajoutée quand les couleurs neutres sont actives */
            .neutral-colors .mono-version {
              opacity: 1;
            }

            .neutral-colors .color-version {
              opacity: 0;
            }

            /* Transition pour les tooltips */
            .tool-tooltip {
              transition: background-color 0.5s ease, color 0.5s ease, opacity 0.3s ease, transform 0.3s ease;
            }
          </style>
        `);

        // Définir la couleur neutre en fonction du mode
        function getNeutralColor() {
            return isDarkMode ? '#F5E6CA' : '#142A30';
        }

        // Charger l'état depuis localStorage
        const savedColorMode = localStorage.getItem('brandColorsEnabled');
        if (savedColorMode === 'true') {
            colorToggle.checked = true;
            applyBrandColors();
        } else {
            colorToggle.checked = false;
            applyNeutralColor();
        }

        // Fonction pour appliquer les couleurs de marque
        function applyBrandColors() {
            // Enlever la classe neutral-colors de tous les SVG pour montrer les versions couleur
            svgIcons.forEach(svg => {
                svg.classList.remove('neutral-colors');
            });

            svgIcons.forEach(svg => {
                // Traiter les SVG avec versions mono/couleur séparées
                if (svg.getAttribute('data-mono-svg') === 'true') {
                    // Rien à faire ici, car les versions sont gérées par CSS
                } else {
                    // Traiter les SVG normaux comme avant
                    const brandColorsAttr = svg.getAttribute('data-brand-colors');

                    if (brandColorsAttr) {
                        try {
                            const brandColors = JSON.parse(brandColorsAttr);
                            const parts = svg.querySelectorAll('.svg-part');

                            parts.forEach(part => {
                                const partName = part.getAttribute('data-part');

                                // Gestion spéciale des dégradés pour PhpStorm
                                if (partName === 'gradA') {
                                    part.setAttribute('fill', 'url(#phpstorm-a)');
                                } else if (partName === 'gradB') {
                                    part.setAttribute('fill', 'url(#phpstorm-b)');
                                } else if (partName === 'gradC') {
                                    part.setAttribute('fill', 'url(#phpstorm-c)');
                                } else if (partName === 'gradWarp') {
                                    part.setAttribute('fill', 'url(#warp-color-gradient)');
                                } else if (partName === 'main') {
                                    part.setAttribute('fill', brandColors.main || '#ED70A7');
                                } else if (partName === 'shadow') {
                                    part.setAttribute('fill', brandColors.shadow || '#D35198');
                                } else if (partName === 'eye') {
                                    part.setAttribute('fill', brandColors.eye || '#FFFFFF');
                                } else if (partName === 'pupil') {
                                    part.setAttribute('fill', brandColors.pupil || '#272D63');
                                } else if (partName === 'reflection') {
                                    part.setAttribute('fill', brandColors.reflection || '#FFFFFF');
                                } else if (partName === 'gradAngularA') {
                                    part.setAttribute('fill', 'url(#angular-a)');
                                } else if (partName === 'gradAngularB') {
                                    part.setAttribute('fill', 'url(#angular-b)');
                                } else if (partName === 'gradAngularC') {
                                    part.setAttribute('fill', 'url(#angular-c)');
                                } else if (partName === 'gradAngularD') {
                                    part.setAttribute('fill', 'url(#angular-d)');
                                } else if (partName === 'gradTrello') {
                                    part.setAttribute('fill', 'url(#trello-color-gradient)');
                                } else if (partName === 'top-bar') {
                                    part.setAttribute('fill', '#fec514');
                                } else if (partName === 'middle-bar') {
                                    part.setAttribute('fill', '#343741');
                                } else if (partName === 'bottom-bar') {
                                    part.setAttribute('fill', '#00bfb3');
                                } else if (partName.startsWith('path-') || partName.startsWith('use-')) {
                                    // Pour les nombreux chemins du logo Apache, on conserve leur couleur d'origine (définie par l'URL)
                                    // Le remplissage est déjà configuré dans le SVG
                                } else if (partName === 'apache-mono') {
                                    // Pas besoin de le remplir explicitement car c'est déjà défini avec url(#apache-mono-gradient)
                                } else if (partName && brandColors[partName]) {
                                    // Traitement normal pour les autres parties
                                    part.setAttribute('fill', brandColors[partName]);
                                }
                            });
                        } catch (e) {
                            console.error('Erreur lors du parsing des couleurs:', e);
                        }
                    } else {
                        const brandColor = svg.getAttribute('data-brand-color');
                        if (brandColor) {
                            svg.style.fill = brandColor;
                        }
                    }
                }

                // Gestion du tooltip
                const tooltipEl = svg.closest('.relative').querySelector('.tool-tooltip');
                if (tooltipEl) {
                    // Pour les SVG multicolores, utiliser la couleur principale pour le tooltip
                    let tooltipColor;
                    const brandColorsAttr = svg.getAttribute('data-brand-colors');

                    if (brandColorsAttr) {
                        try {
                            const brandColors = JSON.parse(brandColorsAttr);
                            // Vérifier si un tooltip personnalisé est défini
                            if (brandColors.tooltip) {
                                // Vérifier si c'est un tableau de couleurs (pour un dégradé)
                                if (brandColors.tooltip.includes(',')) {
                                    // Créer un dégradé linéaire pour le background
                                    const colors = brandColors.tooltip.split(',');
                                    let gradient = 'linear-gradient(135deg';

                                    // Ajouter chaque couleur au dégradé
                                    colors.forEach((color, index) => {
                                        const percentage = index * (100 / (colors.length - 1));
                                        gradient += `, ${color.trim()} ${percentage}%`;
                                    });

                                    gradient += ')';
                                    tooltipEl.style.backgroundImage = gradient;
                                    tooltipEl.style.backgroundColor = 'transparent';
                                } else {
                                    // Couleur unique
                                    tooltipEl.style.backgroundImage = '';
                                    tooltipEl.style.backgroundColor = brandColors.tooltip;
                                }
                            } else {
                                // Utiliser la couleur du logo ou la première couleur disponible
                                tooltipColor = brandColors.logo || Object.values(brandColors)[0];
                                tooltipEl.style.backgroundImage = '';
                                tooltipEl.style.backgroundColor = tooltipColor;
                            }

                            // Déterminer si le texte doit être clair ou foncé en fonction de la couleur dominante
                            // Pour un dégradé, on utilise la première couleur comme référence
                            let colorToCheck = brandColors.tooltip ?
                                brandColors.tooltip.split(',')[0].trim() : tooltipColor;

                            const r = parseInt(colorToCheck.substr(1, 2), 16);
                            const g = parseInt(colorToCheck.substr(3, 2), 16);
                            const b = parseInt(colorToCheck.substr(5, 2), 16);
                            const brightness = (r * 299 + g * 587 + b * 114) / 1000;

                            tooltipEl.style.color = brightness > 128 ? '#000000' : '#FFFFFF';
                        } catch (e) {
                            console.error('Erreur lors du parsing des couleurs:', e);
                            tooltipEl.style.backgroundColor = getNeutralColor();
                        }
                    } else {
                        tooltipColor = svg.getAttribute('data-brand-color') || getNeutralColor();
                        tooltipEl.style.backgroundImage = '';
                        tooltipEl.style.backgroundColor = tooltipColor;

                        const r = parseInt(tooltipColor.substr(1, 2), 16);
                        const g = parseInt(tooltipColor.substr(3, 2), 16);
                        const b = parseInt(tooltipColor.substr(5, 2), 16);
                        const brightness = (r * 299 + g * 587 + b * 114) / 1000;

                        tooltipEl.style.color = brightness > 128 ? '#000000' : '#FFFFFF';
                    }
                }
            });
        }

        // Fonction pour appliquer la couleur neutre
        function applyNeutralColor() {
            const baseNeutralColor = getNeutralColor(); // #142A30 en mode clair, #F5E6CA en mode sombre
            const isDarkMode = document.documentElement.classList.contains('dark');

            // Définir les couleurs du dégradé pour le mode monochrome
            const gradientStart = isDarkMode ? '#F5E6CA' : '#142A30'; // Couleur de départ du dégradé
            const gradientEnd = isDarkMode ? '#FFFFFF' : '#6A7577';   // Couleur de fin du dégradé

            // Ajouter la classe neutral-colors à tous les SVG pour montrer les versions mono
            svgIcons.forEach(svg => {
                svg.classList.add('neutral-colors');

                // Pour les SVG avec double version
                if (svg.getAttribute('data-mono-svg') === 'true') {
                    // Appliquer la couleur neutre à la version mono
                    const monoVersion = svg.querySelector('.mono-version');
                    if (monoVersion) {
                        monoVersion.setAttribute('fill', baseNeutralColor);
                    }
                } else {
                    // Pour les SVG normaux
                    if (svg.getAttribute('data-brand-colors')) {
                        // Pour les SVG multicolores, appliquer le dégradé ou la couleur neutre à chaque partie
                        const parts = svg.querySelectorAll('.svg-part');

                        // Vérifier si c'est le logo PhpStorm avec dégradés
                        const hasGradients = Array.from(parts).some(part =>
                            ['gradA', 'gradB', 'gradC'].includes(part.getAttribute('data-part'))
                        );
                        // Vérifier si c'est le logo Warp Terminal avec dégradés
                        const hasWarpGradient = Array.from(parts).some(part =>
                            ['full-right', 'gradWarp'].includes(part.getAttribute('data-part'))
                        );
                        // Vérifier si c'est le logo Livewire
                        const hasLivewireParts = Array.from(parts).some(part =>
                            ['mono-main', 'mono-shadow', 'mono-pupil'].includes(part.getAttribute('data-part'))
                        );
                        // Vérifier si c'est le logo AlpineJS
                        const hasAlpineParts = Array.from(parts).some(part =>
                            ['mono-left', 'mono-right'].includes(part.getAttribute('data-part'))
                        );
                        // Vérifier si c'est le logo DaisyUI
                        const hasDaisyUIParts = Array.from(parts).some(part =>
                            ['mono-center', 'mono-circle', 'mono-bottom'].includes(part.getAttribute('data-part'))
                        );
                        // Vérifier si c'est le logo Angular
                        const hasAngularParts = Array.from(parts).some(part =>
                            ['mono-angularA', 'mono-angularB', 'mono-angularC', 'mono-angularD'].includes(part.getAttribute('data-part'))
                        );
                        // Vérifier si c'est le logo Trello
                        const hasTrelloGradient = Array.from(parts).some(part =>
                            ['gradTrello'].includes(part.getAttribute('data-part'))
                        );
                        // Vérifier si c'est le logo Elasticsearch
                        const hasElasticParts = Array.from(parts).some(part =>
                            ['top-bar', 'middle-bar', 'bottom-bar'].includes(part.getAttribute('data-part'))
                        );
                        // Vérifier si c'est le logo Apache
                        const hasApacheParts = Array.from(parts).some(part =>
                            part.getAttribute('data-part') === 'apache-mono'
                        );

                        if (hasGradients || hasWarpGradient || hasTrelloGradient || hasLivewireParts || hasAlpineParts || hasDaisyUIParts || hasAngularParts || hasElasticParts || hasApacheParts) {

                            // Créer des dégradés pour PhpStorm avec des orientations différentes
                            const svgNS = "http://www.w3.org/2000/svg";
                            const defsElement = svg.querySelector('defs') || document.createElementNS(svgNS, 'defs');

                            // Supprimez les anciens dégradés s'ils existent
                            const oldGradients = svg.querySelectorAll('[id^="mono-gradient-"]');
                            oldGradients.forEach(oldGradient => oldGradient.remove());

                            // Configuration des dégradés pour chaque forme
                            const gradientConfigs = {
                                // Pour PhpStorm
                                'gradA': { id: 'mono-gradient-a', x1: '0%', y1: '100%', x2: '100%', y2: '0%' }, // Diagonale bas-gauche vers haut-droite
                                'gradB': { id: 'mono-gradient-b', x1: '0%', y1: '0%', x2: '100%', y2: '100%' }, // Diagonale haut-gauche vers bas-droit
                                'gradC': { id: 'mono-gradient-c', x1: '100%', y1: '50%', x2: '0%', y2: '50%' }, // linéaire milieu droite à gauche
                                // Pour Warp
                                'full-right': { id: 'mono-gradient-warp', x1: '0%', y1: '100%', x2: '100%', y2: '0%' },
                                // Pour Angular - tous les éléments utilisent le même dégradé
                                'mono-angularA': { id: 'mono-gradient-angular', x1: '0%', y1: '100%', x2: '100%', y2: '0%' },
                                // Pour Trello
                                'full': { id: 'mono-gradient-trello', x1: '0%', y1: '100%', x2: '100%', y2: '0%' },
                            };

                            // Créer chaque dégradé
                            Object.values(gradientConfigs).forEach(config => {
                                const gradientElement = document.createElementNS(svgNS, 'linearGradient');
                                gradientElement.setAttribute('id', config.id);
                                gradientElement.setAttribute('x1', config.x1);
                                gradientElement.setAttribute('y1', config.y1);
                                gradientElement.setAttribute('x2', config.x2);
                                gradientElement.setAttribute('y2', config.y2);

                                // Pour Angular, on inverse les couleurs du dégradé (clair en bas à gauche, foncé en haut à droite)
                                if (config.id === 'mono-gradient-angular') {
                                    const stop1 = document.createElementNS(svgNS, 'stop');
                                    stop1.setAttribute('offset', '0%');
                                    stop1.setAttribute('stop-color', '#6A7577'); // Gris clair

                                    const stop2 = document.createElementNS(svgNS, 'stop');
                                    stop2.setAttribute('offset', '100%');
                                    stop2.setAttribute('stop-color', '#142A30'); // Bleu foncé

                                    gradientElement.appendChild(stop1);
                                    gradientElement.appendChild(stop2);
                                } else {
                                    // Dégradés standard pour les autres logos
                                    const stop1 = document.createElementNS(svgNS, 'stop');
                                    stop1.setAttribute('offset', '0%');
                                    stop1.setAttribute('stop-color', gradientStart);

                                    const stop2 = document.createElementNS(svgNS, 'stop');
                                    stop2.setAttribute('offset', '100%');
                                    stop2.setAttribute('stop-color', gradientEnd);

                                    gradientElement.appendChild(stop1);
                                    gradientElement.appendChild(stop2);
                                }

                                defsElement.appendChild(gradientElement);
                            });

                            // Ajouter les defs au SVG si ce n'est pas déjà fait
                            if (!svg.querySelector('defs')) {
                                svg.insertBefore(defsElement, svg.firstChild);
                            }

                            // Appliquer les dégradés spécifiques à chaque partie
                            parts.forEach(part => {
                                const partName = part.getAttribute('data-part');

                                if (partName === 'gradA') {
                                    part.setAttribute('fill', 'url(#mono-gradient-a)');
                                } else if (partName === 'gradB') {
                                    part.setAttribute('fill', 'url(#mono-gradient-b)');
                                } else if (partName === 'gradC') {
                                    part.setAttribute('fill', 'url(#mono-gradient-c)');
                                } else if (partName === 'full-right') {
                                    part.setAttribute('fill', 'url(#mono-gradient-warp)');
                                } else if (partName === 'full-left') {
                                    // La partie gauche du logo Warp reste une couleur unie
                                    part.setAttribute('fill', baseNeutralColor);
                                }
                                // Traitement spécifique pour Livewire
                                else if (partName === 'mono-main') {
                                    part.setAttribute('fill', baseNeutralColor); // #142A30
                                } else if (partName === 'mono-shadow') {
                                    part.setAttribute('fill', '#05181C'); // Bleu gris foncé
                                } else if (partName === 'mono-pupil') {
                                    part.setAttribute('fill', baseNeutralColor); // #142A30
                                }
                                // Traitement spécifique pour AlpineJS
                                else if (partName === 'mono-left') {
                                    part.setAttribute('fill', baseNeutralColor); // #142A30
                                } else if (partName === 'mono-right') {
                                    part.setAttribute('fill', '#6A7577'); // Gris clair
                                }
                                // Traitement spécifique pour DaisyUI
                                else if (partName === 'mono-center') {
                                    part.setAttribute('fill', baseNeutralColor); // #142A30 pour le rond jaune
                                } else if (partName === 'mono-circle') {
                                    part.setAttribute('fill', '#6A7577'); // Gris clair pour le cercle externe
                                } else if (partName === 'mono-bottom') {
                                    part.setAttribute('fill', baseNeutralColor); // #142A30 pour le rectangle arrondi vert
                                }
                                // Traitement spécifique pour Angular - toutes les parties utilisent le même dégradé
                                else if (partName === 'mono-angularA' || partName === 'mono-angularB' ||
                                    partName === 'mono-angularC' || partName === 'mono-angularD') {
                                    part.setAttribute('fill', 'url(#mono-gradient-angular)');
                                }
                                else if (partName === 'full' && hasTrelloGradient) {
                                    part.setAttribute('fill', 'url(#mono-gradient-trello)');
                                } else if (partName === 'top-bar' && hasElasticParts) {
                                    part.setAttribute('fill', '#6A7577'); // Barre supérieure en gris clair
                                } else if (partName === 'middle-bar' && hasElasticParts) {
                                    part.setAttribute('fill', '#142A30'); // Barre du milieu en bleu très foncé
                                } else if (partName === 'bottom-bar' && hasElasticParts) {
                                    part.setAttribute('fill', '#6A7577'); // Barre inférieure en gris clair
                                }
                                else {
                                    // Autres parties avec couleur neutre standard
                                    part.setAttribute('fill', baseNeutralColor);
                                }
                            });
                        } else {
                            // Traitement normal pour les autres SVG multicolores
                            parts.forEach(part => {
                                part.setAttribute('fill', baseNeutralColor);
                            });
                        }
                    } else {
                        // Pour les SVG monochromes
                        svg.style.fill = baseNeutralColor;
                    }
                }

                // Réinitialiser complètement les tooltips
                const tooltipEl = svg.closest('.relative').querySelector('.tool-tooltip');
                if (tooltipEl) {
                    // Réinitialiser toutes les propriétés pertinentes
                    tooltipEl.style.backgroundColor = '';
                    tooltipEl.style.backgroundImage = '';
                    tooltipEl.style.background = '';  // Réinitialiser la propriété abrégée aussi
                    tooltipEl.style.color = '';

                    // En mode monochrome, nous voulons être certains qu'aucun gradient n'est appliqué
                    tooltipEl.removeAttribute('style');  // Supprime tous les styles inline
                }
            });
        }

        // Écouteur d'événement pour le toggle
        colorToggle.addEventListener('change', function() {
            if (this.checked) {
                applyBrandColors();
                localStorage.setItem('brandColorsEnabled', 'true');
            } else {
                applyNeutralColor();
                localStorage.setItem('brandColorsEnabled', 'false');
            }
        });

        // Écouter les changements de mode sombre/clair (comme avant)
        const themeToggle = document.getElementById('theme-toggle');
        if (themeToggle) {
            themeToggle.addEventListener('change', function() {
                setTimeout(() => {
                    if (!colorToggle.checked) {
                        applyNeutralColor();
                    }
                }, 100);
            });
        }

        // Animation améliorée au survol (comme avant)
        svgIcons.forEach(svg => {
            const card = svg.closest('.tool-card');

            card.addEventListener('mouseenter', function() {
                svg.classList.add('animate-pulse');
            });

            card.addEventListener('mouseleave', function() {
                svg.classList.remove('animate-pulse');
                svg.style.filter = '';
            });
        });
    });
</script>
